monolith 3
# imports.map -- a test package for `import` (docs/map-format.md 2.10; MAP.md). This main file
# imports parts/a.map (which imports parts/nested/c.map) and parts/b.map. imports-flat.map is the
# same map in one file: keep the two in step.

env sun.direction 0.4 -0.8 0.45
env shadow.size 2048
env sun.range 60
env volumetricFog.enabled off

spawn 0 0 14 180
viewpoint "Overview" 0 9 18 0 1 -6
viewpoint "Parts" -12 3 4 -4 0.5 -10
viewpoint "Paint" 7 2.5 2 4 1 -4

material "ground" albedo 118 112 100 roughness 0.95
material "stone" albedo 150 146 138 roughness 0.85
material "brick" albedo 160 80 60 roughness 0.9

group "ground"
use "ground"
box -30 -1 -30 30 0 30

group "main: before the imports"
use "stone"
block -8 0 -8 2 3 2
import "parts/a.map"
group "main: between the imports"
box -10 0 -4 -8 1 -2
use "brick"
import "./parts//b.map"
group "main: after the imports"
block 8 0 -8 2 3 2
use "default"
light point 0 3 0 color 255 200 150 energy 4 range 12 shadow on
